import * as core from './upstream-exchange-core.mjs';
import {upstreamCopy as copy} from './upstream-exchange-content.mjs';
import {upstreamEnvelope,upstreamPostDrawing,upstreamQuestionIcon,upstreamDrawingText,upstreamVisibleDrawingText} from './upstream-exchange-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const p=t=>`<p>${esc(t)}</p>`,button=(t,a='',primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${a}>${esc(t)}</button>`;
const raw=x=>{try{return JSON.stringify(x,null,2);}catch{return 'Original saved data is unavailable to display.';}};
const refused='This action was not recorded. Your kept question and reply have not changed. You can download your notes.';
const damage='Some saved question or support records cannot be read. Readable questions and kept replies remain available; original data stays in your notes.';
let visits=new WeakMap();
export function resetUpstreamView(state){if(state&&typeof state==='object')visits.delete(state);else visits=new WeakMap();}
function visit(state,explorerId=''){let u=visits.get(state);if(!u||u.explorerId!==explorerId){const v=core.upstreamView(state),id=v.selectedQuestionId||null;u={explorerId,id,phase:id?(v.questions?.find(q=>q.id===id)?.post?'postbag':'question'):'counter',format:'short',highlight:'',helper:false};visits.set(state,u);}return u;}
const selected=(v,u)=>v.questions?.find(q=>q.id===u.id);
const original=v=>(v.status==='ready'||v.status==='missing')&&v.source?`<details class="upstream-source"><summary>Original letter</summary><div class="upstream-letter"><h3>${esc(v.source.title)}</h3>${v.source.letter.map(p).join('')}${p(v.source.origin)}</div></details>`:'';
function choices(v,u){return `<div class="upstream-choices" role="group" aria-label="Choose a useful question">${(v.questions||[]).map((q,i)=>`<button type="button" class="secondary" data-upstream-question="${esc(q.id)}" ${!v.canSelect&&!q.post?'disabled':''} aria-pressed="${u.id===q.id}">${upstreamQuestionIcon(i)}<span>${esc(q.source.label)}${q.post?'<br>Question kept in the postbag':''}</span></button>`).join('')}</div>`;}
function speak(v,u,q,host=null){const drawing=u.phase==='reply'?[host?.querySelector('.upstream-drawing-readout')?.textContent||upstreamVisibleDrawingText(v.source.post),...(u.highlight?[upstreamDrawingText(v.source.post,u.highlight)]:[]),...Array.from(host?.querySelectorAll('.upstream-sketch-description[open] p')||[],el=>el.textContent)]:[];return [q.source.question,...(u.phase==='reply'?(u.format==='longer'?q.source.longer:q.source.short):[]),...drawing,...(u.helper?[copy.help,...q.source.help]:[])].join(' ');}
function support(v,u,q){return `<div class="upstream-support">${q.canSupport?hearButton(speak(v,u,q),'Hear'):''}${button('Help',`data-upstream-help ${!q.canSupport?'disabled':''}`)}${button(q.support?.together?copy.together:'Exploring together',`data-upstream-together ${!q.canSupport?'disabled':''}`)}</div>${u.helper?`<aside class="upstream-helper"><h3>Help with a useful question</h3>${p(copy.help)}${q.source.help.map(p).join('')}${button('Close help','data-upstream-close-help')}</aside>`:''}`;}
function turn(v,u){const q=selected(v,u);if(!q||u.phase==='counter')return `<div class="upstream-turn"><div><h2 id="upstream-focus" tabindex="-1">${esc(copy.introduction)}</h2>${upstreamEnvelope()}${p('Every question here is useful. Choose what you want to find out.')}</div>${choices(v,u)}</div>`;if(u.phase==='reply'&&!q.post)u.phase='question';const source=q.source;let material,aside;
if(u.phase==='reply'){material=`<article class="upstream-letter"><h2 id="upstream-focus" tabindex="-1">Nuria's reply</h2><p><strong>Your supplied question</strong></p>${p(source.question)}<div class="upstream-formats" role="group" aria-label="Reply format">${button(copy.shorter,`data-upstream-format="short" aria-pressed="${u.format==='short'}"`)}${button(copy.longer,`data-upstream-format="longer" aria-pressed="${u.format==='longer'}"`)}</div><div data-upstream-reply-text>${(u.format==='longer'?source.longer:source.short).map(p).join('')}</div>${q.replyOpened!==true&&!q.canOpen?p('You can read this kept reply. Its opening cannot be recorded with the current saved data.'):''}${support(v,u,q)}<div class="upstream-actions">${button(u.phase==='question'?'Change question':'Back to questions','data-upstream-back')}</div></article>`;aside=`${upstreamPostDrawing(v.source.post,u.highlight)}<div class="upstream-highlights" role="group" aria-label="Explore the sketch">${button('Starting line',`data-upstream-highlight="reference" aria-pressed="${u.highlight==='reference'}"`)}${button('Equal marks',`data-upstream-highlight="marks" aria-pressed="${u.highlight==='marks'}"`)}${button('Reported estimate',`data-upstream-highlight="estimate" aria-pressed="${u.highlight==='estimate'}"`)}</div>`;}
else if(u.phase==='postbag'&&q.post){material=`<article class="upstream-question-paper">${upstreamEnvelope()}<h2 id="upstream-focus" tabindex="-1">To Nuria · Vadoalto</h2>${p(source.question)}${p(copy.postbag)}<div class="upstream-actions">${button(q.replyOpened===true?copy.rereadReply:copy.openReply,'data-upstream-open',true)}</div>${support(v,u,q)}<div class="upstream-actions">${button(u.phase==='question'?'Change question':'Back to questions','data-upstream-back')}</div></article>`;aside=`<h3>A question kept for the next post round</h3>${p('This is a local story postbag. No actual message is sent.')}${p('The next post round happens when you open the reply. There is no real wait.')}`;}
else{material=`<article class="upstream-question-paper"><h2 id="upstream-focus" tabindex="-1">${esc(source.label)}</h2><p data-upstream-question-text>${esc(source.question)}</p><div class="upstream-actions">${q.post?button('Return to the kept envelope','data-upstream-kept',true):button(copy.post,`data-upstream-post ${!q.canPost?'disabled':''}`,true)}</div>${!q.canPost&&!q.post?p('This question cannot be posted with the current saved data. Other readable questions remain available.'):''}${support(v,u,q)}<div class="upstream-actions">${button(u.phase==='question'?'Change question':'Back to questions','data-upstream-back')}</div></article>`;aside=`${upstreamEnvelope()}${p('One complete supplied sentence will go into your postbag.')}`;}
return `<div class="upstream-turn">${material}<div>${aside}</div></div>`;}
export function upstreamPage(state,explorerId=''){const v=core.upstreamView(state),u=visit(state,explorerId);let body;if(v.status==='missing'||!state?.story||!Object.hasOwn(state.story,'upstreamExchange'))body=`<div class="upstream-turn"><div>${upstreamEnvelope()}<h2 id="upstream-focus" tabindex="-1">A reply to Nuria</h2>${p(copy.introduction)}</div><div>${v.canStart?button(copy.start,'data-upstream-start',true):p('Open Nuria’s first letter to begin this exchange.')}<div class="upstream-actions"><a href="#almanac/upstream-letter">Nuria’s first letter</a><a href="#arrive">Begin with an arrival</a></div></div></div>`;else if(v.status==='ready'&&v.source&&v.questions?.length)body=`${v.sectionNotice?p(damage):''}${turn(v,u)}`;else body=`${upstreamEnvelope()}<h2 id="upstream-focus" tabindex="-1">This exchange cannot be read here</h2>${p('Your original saved data is kept in the notebook. Download your notes to preserve it.')}`;return `<section data-upstream-view><header class="upstream-heading"><h1>${esc(copy.title)}</h1><nav><a href="#almanac/upstream-letter">Nuria's first letter</a><a href="#notes">Grown-up notes</a></nav></header><p id="upstream-status" class="upstream-status" role="status" aria-live="polite" tabindex="-1"></p><div class="upstream-counter">${body}</div>${p(copy.ownWords)}${original(v)}<footer class="upstream-footer">${button('Download our notes','data-upstream-download')}<a href="#desk">Keeper's Desk</a></footer></section>`;}
export function upstreamNotes(state){try{if(!state?.story||!Object.hasOwn(state.story,'upstreamExchange'))return '';const v=core.upstreamView(state);if(v.status==='missing')return '';return `<details class="panel upstream-notes"><summary>Upstream Post</summary>${p(copy.notesDisclaimer)}${v.status==='ready'&&v.source?`${p(v.source.title)}${p(v.source.origin)}${v.sectionNotice?p(damage):''}${v.questions.map(q=>`<section><h3>${esc(q.source.label)}</h3>${p(q.source.question)}${p(q.post?'Supplied question posted in the local story postbag.':q.postStatus==='unavailable'?'Saved post record unavailable.':'No post recorded.')}${q.post?`${p(q.replyOpened===true?'Reply opening recorded.':q.replyOpened===null?'Reply opening record unavailable.':'No reply opening recorded.')}<h4>Support recorded before posting</h4>${['help','narration','together'].map(key=>p(`${key==='narration'?'narration requested':key}: ${q.post.posted.supportBefore[key]?'recorded':'not recorded'}`)).join('')}<h4>Kept reply</h4>${q.source.short.map(p).join('')}`:''}${p(q.supportStatus==='unavailable'?'Current support record unavailable.':`Current support: help ${q.support.help?'recorded':'not recorded'}; narration requested ${q.support.narration?'recorded':'not recorded'}; together ${q.support.together?'recorded':'not recorded'}.`)}</section>`).join('')}${p(upstreamDrawingText(v.source.post))}`:p('Saved exchange unavailable; original data is preserved below.')}<details><summary>Original saved exchange data</summary><pre>${esc(raw(state.story?.upstreamExchange))}</pre></details></details>`;}catch{return `<details class="panel upstream-notes"><summary>Upstream Post</summary>${p('Saved exchange unavailable. Original story data remains in your notebook export.')}</details>`;}}
export function bindUpstream(state,{notebook=()=>state,explorerId=()=>'',isActive=()=>true,save,render,focus,canExport,download,stopSpeech,stopSound}={}){const host=document.querySelector('[data-upstream-view]');if(!host)return;const u=visit(state,explorerId()),boundExplorer=explorerId(),boundPhase=u.phase,boundId=u.id,boundFormat=u.format,boundHighlight=u.highlight,boundHelper=u.helper;let boundStory=state.story;const live=el=>document.querySelector('[data-upstream-view]')===host&&host.isConnected&&el.isConnected&&!el.closest('[hidden]')&&el.getClientRects().length>0&&notebook()===state&&state.story===boundStory&&explorerId()===boundExplorer&&isActive()&&window.location.hash==='#almanac/upstream-reply'&&!document.querySelector('dialog[open]')&&visits.get(state)===u&&u.phase===boundPhase&&u.id===boundId&&u.format===boundFormat&&u.highlight===boundHighlight&&u.helper===boundHelper;
 const status=(text,take=false)=>{const box=host.querySelector('#upstream-status');if(box){box.textContent=text;if(take)box.focus();}};
 const persist=()=>{try{const r=save?.();return r?.enabled===false?'Saving is off. This exchange is in this session; download your notes to keep it.':r?.ok===false?'Device saving failed. This exchange is in this session; download your notes to keep it.':'';}catch{return 'Device saving failed. This exchange is in this session; download your notes to keep it.';}};
 const redraw=(message='',changed=false,target='#upstream-focus')=>{const note=changed?persist():'';stopSpeech?.();stopSound?.();render?.();const next=document.querySelector('[data-upstream-view]');if(!next)return;const box=next.querySelector('#upstream-status');if(box)box.textContent=note||message;const el=next.querySelector(target);if(el)el.focus();else focus?.();};
 const action=fn=>{const before=state.story;let ok=false;try{ok=fn()===true;}catch{}if(!ok){status(refused,true);return null;}return {changed:state.story!==before};};
 const bind=(selector,fn)=>host.querySelectorAll(selector).forEach(el=>el.addEventListener('click',event=>{if(!live(el)){event.preventDefault();event.stopImmediatePropagation();return;}fn(el,event);}));
 bind('[data-upstream-download]',()=>download?.());
 bind('[data-upstream-start]',()=>{const r=action(()=>core.startUpstream(state,{canExport}));if(!r)return;u.id=null;u.phase='counter';redraw('',r.changed);});
 bind('[data-upstream-question]',el=>{const id=el.dataset.upstreamQuestion,v=core.upstreamView(state),q=v.questions.find(q=>q.id===id);if(!q)return;let changed=false;if(v.canSelect){const r=action(()=>core.selectUpstreamQuestion(state,id,{canExport}));if(!r)return;changed=r.changed;}else if(!q.post)return;u.id=id;u.phase=q.post?'postbag':'question';u.format='short';u.highlight='';u.helper=false;redraw('',changed);});
 bind('[data-upstream-post]',()=>{const r=action(()=>core.postUpstreamQuestion(state,u.id,{canExport}));if(!r)return;u.phase='postbag';u.helper=false;redraw('',r.changed);});
 bind('[data-upstream-kept]',()=>{u.phase='postbag';u.helper=false;redraw();});
 bind('[data-upstream-open]',()=>{const q=selected(core.upstreamView(state),u);if(!q?.post)return;let changed=false;if(q.canOpen){const r=action(()=>core.openUpstreamReply(state,u.id,{canExport}));if(r)changed=r.changed;else{u.phase='reply';u.helper=false;redraw('Read-only reply: this opening was not recorded.',false);return;}}u.phase='reply';u.helper=false;redraw(q.canOpen?'':'Read-only reply: this opening was not recorded.',changed);});
 bind('[data-upstream-back]',()=>{u.phase='counter';u.helper=false;u.highlight='';redraw();});
 bind('[data-upstream-format]',el=>{u.format=el.dataset.upstreamFormat;redraw('',false,`[data-upstream-format="${u.format}"]`);});
 bind('[data-upstream-highlight]',el=>{u.highlight=el.dataset.upstreamHighlight;redraw('',false,`[data-upstream-highlight="${u.highlight}"]`);});
 bind('[data-upstream-help]',()=>{const r=action(()=>core.useUpstreamSupport(state,u.id,'help',{canExport}));if(!r)return;u.helper=true;redraw('',r.changed,'[data-upstream-close-help]');});
 bind('[data-upstream-close-help]',()=>{u.helper=false;redraw('',false,'[data-upstream-help]');});
 bind('[data-upstream-together]',()=>{const r=action(()=>core.useUpstreamSupport(state,u.id,'together',{canExport}));if(r)redraw(copy.together,r.changed,'[data-upstream-together]');});
 host.querySelectorAll('[data-speak]').forEach(el=>el.addEventListener('click',event=>{if(!live(el)){event.preventDefault();event.stopImmediatePropagation();return;}const r=action(()=>core.useUpstreamSupport(state,u.id,'narration',{canExport}));if(!r){event.preventDefault();event.stopImmediatePropagation();return;}if(r.changed){boundStory=state.story;const note=persist();if(note)status(note);}const v=core.upstreamView(state),q=selected(v,u);if(q)el.dataset.speak=speak(v,u,q,host);},true));
}
